use super::*;
use refract_core::{Block,BlockKind,Item,SourceType};
fn allow(s:&Store,id:&str,c:&str){s.integration_set_policy(&IntegrationPolicy{connector_id:id.into(),enabled:true,categories:vec![c.into()],..Default::default()}).unwrap();}
fn email()->EmailCopyInput{EmailCopyInput{raw:"From: private@example.test\r\nSubject: Private subject\r\nDate: Mon, 1 Jun 2026 12:00:00 +0200\r\nX-Private: unrelated\r\nContent-Type: text/plain; charset=utf-8\r\n\r\nReceipt for a selected purchase.".into(),..Default::default()}}
fn date_source(s:&mut Store){let item=Item{id:"s".into(),source_url:None,source_type:SourceType::Text,import_ts:1700000000,content_hash:"sourcehash".into(),title:Some("PRIVATE calendar source title".into()),author:None,language:None,extraction_confidence:1.0,status:refract_core::ImportStatus::Ready,blocks:vec![Block{idx:0,kind:BlockKind::Paragraph,text:"Meeting date 2027-01-02, PRIVATE EVIDENCE".into()}]};s.insert_item(&item,b"private original","hash").unwrap();}
fn calendar(s:&Store)->CalendarExportInput{let id:String=s.conn.query_row("SELECT id FROM signal_events LIMIT 1",[],|r|r.get(0)).unwrap();CalendarExportInput{events:vec![CalendarSelection{event_id:id,title:"Reviewed date".into()}],..Default::default()}}
#[test]fn default_denial_and_unimplemented_providers_cannot_be_enabled(){let s=Store::open_in_memory().unwrap();assert!(s.integration_catalog().unwrap().iter().all(|c|!c.policy.enabled));assert!(s.integration_email_preview(&email()).is_err());for id in["gmail","microsoft_mail","android_notifications","unknown"]{assert!(s.integration_set_policy(&IntegrationPolicy{connector_id:id.into(),enabled:true,categories:vec!["receipt".into()],..Default::default()}).is_err());}assert!(s.integration_set_policy(&IntegrationPolicy{connector_id:"selected_email".into(),enabled:true,categories:vec!["all".into()],..Default::default()}).is_err());assert!(s.list_items(100,0).unwrap().is_empty());}
#[test]fn email_preview_persists_nothing_and_import_saves_only_reviewed_copy(){let mut s=Store::open_in_memory().unwrap();allow(&s,"selected_email","receipt");let mut e=email();let p=s.integration_email_preview(&e).unwrap();assert!(s.list_items(100,0).unwrap().is_empty());for secret in["private@example.test","Private subject","Mon, 1 Jun","unrelated"]{assert!(!p.copy_text.contains(secret));}e.review_hash=p.review_hash;let item=s.integration_email_import(&e).unwrap();assert_eq!(item.source_type,SourceType::EmailCopy);let bytes=std::fs::read(s.blob_dir.join(format!("{}.original",item.id))).unwrap();assert_eq!(String::from_utf8(bytes).unwrap(),p.copy_text);assert!(s.get_item(&item.id).unwrap().unwrap().blocks.iter().any(|b|b.text.contains("selected purchase")));}
#[test]fn email_category_scope_review_and_revocation_are_enforced(){let s=Store::open_in_memory().unwrap();allow(&s,"selected_email","receipt");let mut e=email();let p=s.integration_email_preview(&e).unwrap();e.include_sender=true;let selected=s.integration_email_preview(&e).unwrap();assert!(selected.copy_text.contains("Email-declared From (unverified): private@example.test"));assert_ne!(p.review_hash,selected.review_hash);e.category="travel".into();assert!(s.integration_email_preview(&e).is_err());e.category="receipt".into();s.integration_set_policy(&IntegrationPolicy{connector_id:"selected_email".into(),..Default::default()}).unwrap();assert!(s.integration_email_preview(&e).is_err());assert!(s.integration_policy("selected_email").unwrap().categories.is_empty());allow(&s,"selected_email","receipt");assert_ne!(selected.review_hash,s.integration_email_preview(&e).unwrap().review_hash);}
#[test]fn html_attachments_multipart_controls_and_oversized_email_are_rejected(){let s=Store::open_in_memory().unwrap();allow(&s,"selected_email","receipt");for raw in["Content-Type: text/html\r\n\r\n<img src='https://tracker.test'>".into(),"Content-Type: multipart/mixed; boundary=x\r\n\r\n--x\r\nContent-Type: text/plain\r\n\r\nHi\r\n--x--".into(),"Content-Type: text/plain\r\nContent-Disposition: attachment\r\n\r\nHi".into(),"Content-Type: text/plain\r\n\r\nHidden\u{1b}control".into(),"x".repeat(262145)]{let mut e=email();e.raw=raw;assert!(s.integration_email_preview(&e).is_err());}let mut encoded=email();encoded.raw="Subject: =?UTF-8?B?UmVjZWlwdA==?=\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\nSGVsbG8gV29ybGQ=".into();assert!(s.integration_email_preview(&encoded).unwrap().copy_text.contains("Hello World"));}
#[test]fn calendar_requires_confirmation_no_private_metadata_by_default_and_stale_rejected(){let mut s=Store::open_in_memory().unwrap();date_source(&mut s);allow(&s,"calendar_export","confirmed_dates");let mut input=calendar(&s);assert!(s.integration_calendar_preview(&input).is_err());s.signal_review_event(&input.events[0].event_id,"confirmed").unwrap();let p=s.integration_calendar_preview(&input).unwrap();assert!(p.ics.contains("DTSTART;VALUE=DATE:20270102\r\n"));assert!(p.ics.contains("DTEND;VALUE=DATE:20270103\r\n"));for secret in["PRIVATE","VALARM","ATTENDEE","METHOD:REQUEST"]{assert!(!p.ics.contains(secret));}input.prepared_ts=Some(p.prepared_ts);input.review_hash=p.review_hash;assert_eq!(s.integration_calendar_export(&input).unwrap().ics,p.ics);input.include_evidence=true;assert!(s.integration_calendar_export(&input).is_err());assert!(s.integration_calendar_preview(&input).unwrap().ics.contains("PRIVATE EVIDENCE"));input.include_evidence=false;s.conn.execute("UPDATE blocks SET text='No old evidence remains' WHERE item_id='s'",[]).unwrap();assert!(!s.integration_calendar_candidates().unwrap().events[0].source_current);assert!(s.integration_calendar_export(&input).is_err());}
#[test]fn calendar_escaping_folding_and_grant_changes(){let mut s=Store::open_in_memory().unwrap();date_source(&mut s);allow(&s,"calendar_export","confirmed_dates");let mut input=calendar(&s);s.signal_review_event(&input.events[0].event_id,"confirmed").unwrap();input.events[0].title=format!("Title, escaped; {}","é".repeat(80));let p=s.integration_calendar_preview(&input).unwrap();assert!(p.ics.contains("SUMMARY:Title\\, escaped\\;"));assert!(p.ics.split("\r\n").all(|l|l.len()<=75));input.prepared_ts=Some(p.prepared_ts);input.review_hash=p.review_hash;input.events[0].title="Bad\r\nBEGIN:VALARM".into();assert!(s.integration_calendar_preview(&input).is_err());input.events[0].title="Reviewed date".into();let p=s.integration_calendar_preview(&input).unwrap();input.review_hash=p.review_hash;allow(&s,"calendar_export","confirmed_dates");assert!(s.integration_calendar_export(&input).is_err());}
#[test]fn v12_upgrade_preserves_originals_and_defaults_to_no_integrations(){let mut s=Store::open_in_memory().unwrap();date_source(&mut s);s.conn.execute_batch("DROP TABLE integration_policies; UPDATE meta SET value='12' WHERE key='schema_version';").unwrap();s.migrate().unwrap();s.migrate().unwrap();assert!(s.get_item("s").unwrap().is_some());assert!(s.integration_catalog().unwrap().iter().all(|c|!c.policy.enabled));}
